// load_groups loads the `groups` of `rows`, keyed by each row's key.
fn (q UserQuery) load_groups(rows []models.User, fns []fn (GroupQuery) GroupQuery) !map[string][]GroupNode {
	mut sub := q.graph.groups()
	for configure in fns {
		sub = configure(sub)
	}
	if sub.query.limit > 0 || sub.query.offset > 0 {
		prepared := q.graph.client.prepare_edge_query('groups', sub.query)!
		cut := load.link_each(q.graph.client.conn, 'group_users', 'user_id', 'group_id',
			rows.map(it.id.str()), .int, .int, 'groups', 'id', load.Query{
				...prepared
				conds: prepared.conds
			})!
		// the targets by key: the join rows give their order
		found := sub.nodes(load.select_in[models.Group](q.graph.client.conn, 'id',
			load.unique(cut.map(it[1])),
			query: load.Query{ ...prepared, order: '', desc: false, orders: []load.Order{}, limit: 0, offset: 0 }
		)!)!
		mut by_key := map[string]GroupNode{}
		for target in found {
			by_key[target.group.id.str()] = target
		}
		mut cut_linked := map[string][]GroupNode{}
		for pair in cut {
			if target := by_key[pair[1]] {
				cut_linked[pair[0]] << target
			}
		}
		return cut_linked
	}
	pairs := load.link_pairs(q.graph.client.conn, 'group_users', 'user_id',
		'group_id', rows.map(it.id.str()), .int, .int)!
	// each parent's targets in the order of the query: one select per group of
	// parents, so each parent's order comes from one statement
	mut linked := map[string][]GroupNode{}
	for group in load.parent_groups(pairs) {
		targets := sub.nodes(load.select_in[models.Group](q.graph.client.conn, 'id',
			load.unique(group.map(it[1])),
			query: q.graph.client.prepare_edge_query('groups', sub.query)!
		)!)!
		mut parents_of := map[string][]string{}
		for pair in group {
			parents_of[pair[1]] << pair[0]
		}
		for target in targets {
			for parent in parents_of[target.group.id.str()] or { [] } {
				linked[parent] << target
			}
		}
	}
	return linked
}

