// load_liked_gadgets loads the `liked_gadgets` of `rows`, keyed by each row's key.
fn (q UserQuery) load_liked_gadgets(rows []models.User, fns []fn (GadgetQuery) GadgetQuery) !map[string][]GadgetNode {
	mut sub := q.graph.gadgets()
	for configure in fns {
		sub = configure(sub)
	}
	if sub.query.limit > 0 || sub.query.offset > 0 {
		prepared := q.graph.client.prepare_edge_query('gadgets', sub.query)!
		cut := load.link_each(q.graph.client.conn, 'likes', 'user_id', 'gadget_id',
			rows.map(it.id.str()), .int, .i64, 'gadgets', 'id', load.Query{
				...prepared
				conds: prepared.conds
			})!
		// the targets by key: the join rows give their order
		found := sub.nodes(load.select_in[models.Gadget](q.graph.client.conn, 'id',
			load.unique(cut.map(it[1])),
			query: load.Query{ ...prepared, order: '', desc: false, orders: []load.Order{}, limit: 0, offset: 0 }
		)!)!
		mut by_key := map[string]GadgetNode{}
		for target in found {
			by_key[target.gadget.id.str()] = target
		}
		mut cut_linked := map[string][]GadgetNode{}
		for pair in cut {
			if target := by_key[pair[1]] {
				cut_linked[pair[0]] << target
			}
		}
		return cut_linked
	}
	pairs := load.link_pairs(q.graph.client.conn, 'likes', 'user_id',
		'gadget_id', rows.map(it.id.str()), .int, .i64)!
	// each parent's targets in the order of the query: one select per group of
	// parents, so each parent's order comes from one statement
	mut linked := map[string][]GadgetNode{}
	for group in load.parent_groups(pairs) {
		targets := sub.nodes(load.select_in[models.Gadget](q.graph.client.conn, 'id',
			load.unique(group.map(it[1])),
			query: q.graph.client.prepare_edge_query('gadgets', sub.query)!
		)!)!
		mut parents_of := map[string][]string{}
		for pair in group {
			parents_of[pair[1]] << pair[0]
		}
		for target in targets {
			for parent in parents_of[target.gadget.id.str()] or { [] } {
				linked[parent] << target
			}
		}
	}
	return linked
}

